const body = $json.body ?? $json;
const contacts = Array.isArray(body.contacts) ? body.contacts : [];
const syncId = String(body.syncId ?? '').slice(0, 120);
if (!syncId || contacts.length < 1 || contacts.length > 100) throw new Error('Expected 1-100 governed contacts');
const emailPattern = /^[^@\s]+@[^@\s]+\.[^@\s]+$/u;
const clean = (value, maximum) => String(value ?? '').trim().slice(0, maximum);
const nullable = (value, maximum) => { const result = clean(value, maximum); return result || null; };
const seenEmails = new Set();
const governed = contacts.map((contact) => {
  const contactId = clean(contact.contactId, 120);
  const email = clean(contact.email, 254).toLowerCase();
  if (!contactId || !emailPattern.test(email)) throw new Error('Every contact needs a valid contactId and email');
  if (seenEmails.has(email)) throw new Error('Duplicate email in governed batch');
  seenEmails.add(email);
  return {
    contactId, email,
    firstName: clean(contact.firstName, 255),
    lastName: clean(contact.lastName, 255),
    company: nullable(contact.company, 255),
    phone: nullable(contact.phone, 50),
    jobTitle: nullable(contact.jobTitle, 255),
    website: nullable(contact.website, 500),
  };
});
const inputs = governed.map((contact) => {
  const properties = { firstname: contact.firstName, lastname: contact.lastName };
  if (contact.company) properties.company = contact.company;
  if (contact.phone) properties.phone = contact.phone;
  if (contact.jobTitle) properties.jobtitle = contact.jobTitle;
  if (contact.website) properties.website = contact.website;
  return {
    id: contact.email,
    idProperty: 'email',
    objectWriteTraceId: `${syncId}:${contact.contactId}`.slice(0, 255),
    properties,
  };
});
return [{ json: { syncId, sourceFile: clean(body.sourceFile, 255), contacts: governed, inputs } }];

const response = $json;
const batch = $('Validate and Shape HubSpot Batch').item.json;
const results = Array.isArray(response.results) ? response.results : [];
const errors = Array.isArray(response.errors) ? response.errors : [];
const byTrace = new Map(results.map((result) => [String(result.objectWriteTraceId ?? ''), result]));
const errorByTrace = new Map(errors.map((error) => {
  const contextTrace = error.context?.objectWriteTraceId;
  const traceId = Array.isArray(contextTrace) ? String(contextTrace[0] ?? '') : String(contextTrace ?? '');
  return [traceId, error];
}));
const records = batch.contacts.map((contact, index) => {
  const traceId = `${batch.syncId}:${contact.contactId}`.slice(0, 255);
  const result = byTrace.get(traceId) ?? (results.length === batch.contacts.length ? results[index] : null);
  if (result) return { contactId: contact.contactId, email: contact.email, status: 'synced', hubSpotId: String(result.id ?? ''), created: typeof result.new === 'boolean' ? result.new : null, error: null };
  const error = errorByTrace.get(traceId);
  return { contactId: contact.contactId, email: contact.email, status: 'failed', hubSpotId: null, created: null, error: String(error?.message ?? 'HubSpot did not return a result for this record.').slice(0, 1000) };
});
const synced = records.filter((record) => record.status === 'synced').length;
const failed = records.length - synced;
return [{ json: { accepted: true, status: failed ? 'partial' : 'complete', syncId: batch.syncId, requested: records.length, synced, failed, records, completedAt: response.completedAt ?? new Date().toISOString() } }];
